// Cuánto fluido hace falta para llevarse el calor de un rack. Q = caudal x densidad x calor específico x salto de temperatura
const potenciaW = 10000;   // 10 kW de equipos en un rack (ejemplo inventado): toda esa electricidad termina como calor
const aire  = { rho: 1.2,  cp: 1005 };   // kg/m3 y J/(kg·K), valores físicos típicos a ~20 °C
const agua  = { rho: 1000, cp: 4186 };
const dT_aire = 12, dT_agua = 10;        // saltos de temperatura de diseño típicos (ejemplo)

const caudalAire = potenciaW / (aire.rho * aire.cp * dT_aire);   // m3/s
const caudalAgua = potenciaW / (agua.rho * agua.cp * dT_agua);   // m3/s
console.log("aire:", caudalAire.toFixed(2), "m3/s =", (caudalAire * 3600).toFixed(0), "m3/h");
console.log("agua:", (caudalAgua * 1000 * 60).toFixed(1), "litros por minuto");
console.log("cada litro de agua se lleva tanto calor como", Math.round((agua.rho * agua.cp) / (aire.rho * aire.cp)), "litros de aire (mismo salto de temperatura)");

// PUE = energía total de la instalación / energía de los equipos de cómputo
const cargaITkW = 1000;          // 1 MW de equipos de cómputo (ejemplo)
const horasAnio = 8760;
const precioKWh = 0.08;          // USD, precio INVENTADO para ilustrar el método

function anual(pue) {
  const itKWh = cargaITkW * horasAnio;
  const totalKWh = itKWh * pue;
  return { itKWh, totalKWh, extraKWh: totalKWh - itKWh, costo: totalKWh * precioKWh };
}
for (const [nombre, pue] of [["PUE 1,09 (flota Google, primer trim. 2026)", 1.09], ["PUE 1,54 (promedio de la encuesta Uptime 2025)", 1.54], ["PUE 2,0 (el ejemplo de la definición)", 2.0]]) {
  const r = anual(pue);
  console.log(nombre);
  console.log("  energía total:", Math.round(r.totalKWh).toLocaleString("en-US"), "kWh/año");
  console.log("  energía que no es cómputo:", Math.round(r.extraKWh).toLocaleString("en-US"), "kWh/año");
  console.log("  costo a USD", precioKWh, "el kWh: USD", Math.round(r.costo).toLocaleString("en-US"));
}
const dif = anual(1.54).costo - anual(1.09).costo;
console.log("diferencia anual entre 1,54 y 1,09 para 1 MW de cómputo: USD", Math.round(dif).toLocaleString("en-US"));

// Disponibilidad de la cadena de energía con piezas independientes (modelo de juguete)
const a = 0.999;        // disponibilidad de UNA unidad (UPS) -> inventada para el ejemplo
const minAnio = 365 * 24 * 60;
const fmt = (p) => (p * 100).toFixed(4) + "%  ->  " + ((1 - p) * minAnio).toFixed(0) + " min/año sin servicio";

function binom(n, k) { let r = 1; for (let i = 1; i <= k; i++) r = r * (n - k + i) / i; return r; }
// el sistema funciona si al menos 'necesarias' de 'total' unidades funcionan
function alMenos(necesarias, total, p) {
  let s = 0;
  for (let k = necesarias; k <= total; k++) s += binom(total, k) * p ** k * (1 - p) ** (total - k);
  return s;
}
const N = 4;                                   // la carga necesita 4 unidades
const sinRedundancia = alMenos(N, N, a);       // N
const nMas1 = alMenos(N, N + 1, a);            // N+1
const cadena = alMenos(N, N, a);
const dosN = 1 - (1 - cadena) ** 2;            // 2N: dos cadenas completas e independientes

console.log("N   (4 de 4):          ", fmt(sinRedundancia));
console.log("N+1 (4 de 5):          ", fmt(nMas1));
console.log("2N  (dos cadenas de 4):", fmt(dosN));
console.log("Ojo: esto supone fallas independientes. Un incendio o un error de operación que afecte a las dos cadenas rompe el supuesto.");
